def delete_obsolete_generated_views(env):
    """Remove the obsolete noupdate snippet/page templates generated by 19.0.

    Their children are theme customizations of the same generated templates
    (`theme_anelusia.new_page_template_*` without XML-ID), obsolete as well.
    Only noupdate records are listed: the others are removed by Odoo itself.
    """
    env.cr.execute(
        """
        SELECT 'website.' || name FROM ir_model_data
        WHERE module = 'website' AND model = 'ir.ui.view' AND noupdate
            AND name IN %s
        ORDER BY id DESC
        """,
        (tuple(OBSOLETE_GENERATED_VIEWS),),
    )
    xmlids = [row[0] for row in env.cr.fetchall()]
    if xmlids:
        _logger.info("Deleting %s obsolete generated website views", len(xmlids))
        openupgrade.delete_records_safely_by_xml_id(
            env(context=dict(env.context, force_delete=True)),
            xmlids,
            delete_childs=True,
        )


def _db_only_qweb_views_query(cr, condition):
    """Return id, key and arch_db of the QWeb views that are not refreshed
    from module files: COW copies (unless reset to upstream by
    `cow_templates_replicate_upstream`), views without XML-ID (pages, custom
    templates) and noupdate views.
    """
    mark_column = openupgrade.get_legacy_name("cow_equal_to_upstream")
    mark_condition = (
        f"AND v.{mark_column} IS NOT TRUE"
        if openupgrade.column_exists(cr, "ir_ui_view", mark_column)
        else ""
    )
    cr.execute(
        f"""
        SELECT v.id, v.key, v.arch_db
        FROM ir_ui_view v
        WHERE v.type = 'qweb'
            AND v.arch_db IS NOT NULL
            AND ({condition})
            AND (
                (v.website_id IS NOT NULL {mark_condition})
                OR NOT EXISTS (
                    SELECT 1 FROM ir_model_data d
                    WHERE d.model = 'ir.ui.view' AND d.res_id = v.id
                        AND NOT COALESCE(d.noupdate, FALSE)
                )
            )
        ORDER BY v.id
        """
    )
    return cr.fetchall()


def _update_arch_db(cr, view_id, arch_db):
    cr.execute(
        "UPDATE ir_ui_view SET arch_db = %s WHERE id = %s", (Json(arch_db), view_id)
    )


# Python calls in QWeb expressions whose target moved in 20.0: (old, new)
_MOVED_QWEB_CALLS = [
    (
        "['website.visitor']._get_visitor_from_request(",
        "['ir.http']._get_visitor_from_request(",
    ),
]


def fix_moved_qweb_calls(env):
    """Database-only copies (COW pages such as /contactus) keep the 19.0
    expressions; rewrite calls to methods that moved to another model."""
    cr = env.cr
    for old, new in _MOVED_QWEB_CALLS:
        condition = cr.mogrify("v.arch_db::text LIKE %s", ("%" + old + "%",)).decode()
        for view_id, key, arch_db in _db_only_qweb_views_query(cr, condition):
            arch_db = {lang: arch.replace(old, new) for lang, arch in arch_db.items()}
            _update_arch_db(cr, view_id, arch_db)
            _logger.info("View %s (%s): %s -> %s", view_id, key, old, new)


def _social_urls_by_website(cr):
    """Return {website_id: {network: url}} from the legacy `website.social_*`
    columns, completed by the `res.company.social_*` values of the website
    company (19.0 initialized the website values from the company).
    """
    result = {}
    for table in ("website", "res_company"):
        cr.execute(
            """
            SELECT column_name FROM information_schema.columns
            WHERE table_name = %s AND column_name LIKE %s
            ORDER BY column_name
            """,
            (table, r"social\_%"),
        )
        columns = [row[0] for row in cr.fetchall()]
        if not columns:
            continue
        source = "w" if table == "website" else "c"
        cr.execute(
            "SELECT w.id, %s FROM website w JOIN res_company c ON c.id = w.company_id"
            % ", ".join(f"{source}.{column}" for column in columns)
        )
        for row in cr.fetchall():
            values = result.setdefault(row[0], {})
            for column, value in zip(columns, row[1:]):
                if value:
                    values.setdefault(column[len("social_") :], value)
    return result


def social_links_from_website(env):
    """Odoo 20.0 removed the `/website/social/<network>` redirection route
    and the `website.social_*` fields: social media snippets now store the
    real URL. Replace the old route in the views kept from 19.0 by the URL of
    the website of the view (first website for generic views), or by '#'
    when the network is not configured (the 19.0 route answered 404 then).
    Module views are refreshed from the 20.0 files before this runs.
    """
    cr = env.cr
    networks = _social_urls_by_website(cr)
    cr.execute("SELECT id FROM website ORDER BY sequence, id LIMIT 1")
    row = cr.fetchone()
    default_website_id = row and row[0]
    cr.execute(
        """
        SELECT v.id, v.website_id, v.arch_db FROM ir_ui_view v
        WHERE v.arch_db::text LIKE %s
        """,
        ("%/website/social/%",),
    )
    for view_id, website_id, arch_db in cr.fetchall():
        values = networks.get(website_id or default_website_id, {})

        def replace(match, values=values):
            url = values.get(match.group(2)) or "#"
            if url != "#" and "://" not in url:
                url = "https://" + url.lstrip("/")
            return "href=%s%s%s" % (
                match.group(1),
                html.escape(url, quote=True),
                match.group(1),
            )

        new_arch_db = {
            lang: SOCIAL_HREF_RE.sub(replace, arch) if arch else arch
            for lang, arch in arch_db.items()
        }
        if new_arch_db != arch_db:
            _logger.info("View %s: replaced /website/social/ links", view_id)
            _update_arch_db(cr, view_id, new_arch_db)


def _load_upgrade_code(name):
    """Load `odoo/upgrade_code/<name>.py` (its name is not importable)."""
    for base_path in odoo.__path__:
        path = os.path.join(base_path, "upgrade_code", name + ".py")
        if os.path.isfile(path):
            spec = importlib.util.spec_from_file_location(
                "openupgrade_upgrade_code_" + re.sub(r"\W", "_", name), path
            )
            module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(module)
            return module
    return None


def convert_tcall_tset_arch(tcall_module, arch, key):
    """Convert `<t t-call><t t-set/></t>` of one arch string with the Odoo
    20.0 code upgrade script (`19.1-00-t-call.py`). Odoo 20.0 does not pass
    the variables set in the body of a `t-call` to the called template
    anymore. Run during an upgrade (`upgrade_path` set), the script moves the
    `t-set` before the `t-call` and passes the variable as an attribute.

    :return: the converted arch, or None when nothing changes.
    """
    if not arch or "t-set=" not in arch:
        return None
    if "t-call=" not in arch and "t-snippet-call=" not in arch:
        return None
    from odoo.upgrade_code.tools_etree import update_etree

    changed = []

    def callback(root):
        changed.append(tcall_module.change(root, key or ""))

    try:
        new_arch = update_etree(arch, callback)
    except Exception as error:  # pylint: disable=broad-except
        _logger.debug("update_etree failed on %s: %s", key, error)
        new_arch = arch
        changed = []
    if new_arch == arch:
        # update_etree keeps the original text when it cannot rebuild the
        # formatting; fall back to a plain lxml serialization
        root = etree.fromstring(arch)
        if not tcall_module.change(root, key or ""):
            return None
        for element in root.iter(etree.Element):
            element.attrib.pop("__need_dedent__", None)
            element.attrib.pop("__need_dedent_attributes__", None)
        new_arch = etree.tostring(root, encoding="unicode")
    elif not any(changed):
        return None
    etree.fromstring(new_arch)  # never store an unparsable arch
    return new_arch


def tcall_tset_to_attributes(env):
    """Apply `convert_tcall_tset_arch` to every language of the QWeb views
    stored only in the database (module views are refreshed from the 20.0
    files, which are already converted).
    """
    tcall_module = _load_upgrade_code("19.1-00-t-call")
    if tcall_module is None:
        _logger.warning("odoo/upgrade_code/19.1-00-t-call.py not found")
        return
    cr = env.cr
    rows = _db_only_qweb_views_query(
        cr,
        "v.arch_db::text ~ 't-(snippet-)?call=' AND v.arch_db::text ~ 't-set='",
    )
    for view_id, key, arch_db in rows:
        new_arch_db = dict(arch_db)
        for lang, arch in arch_db.items():
            try:
                new_arch = convert_tcall_tset_arch(tcall_module, arch, key)
            except Exception as error:  # pylint: disable=broad-except
                _logger.warning(
                    "View %s (%s, %s): t-call conversion failed: %s",
                    view_id,
                    key,
                    lang,
                    error,
                )
                continue
            if new_arch is not None:
                new_arch_db[lang] = new_arch
        if new_arch_db != arch_db:
            _logger.info("View %s (%s): converted t-set inside t-call", view_id, key)
            _update_arch_db(cr, view_id, new_arch_db)


def create_missing_specific_views(env):
    """Create now the website-specific copies of the new 20.0 extension views
    whose parent was COW'd: Odoo only does it at the very end of
    `_process_end`, after the end-migration scripts, so they would escape the
    validation below.
    """
    modules = list(env.registry.updated_modules)
    if modules:
        env["ir.ui.view"]._create_all_specific_views(modules)


def _views_removed_at_process_end(env):
    """Return the ids of the views `ir.model.data._process_end` will delete
    after the end-migration scripts: views of the updated modules whose
    (updatable) XML-ID was not loaded from the 20.0 files, their
    website-specific copies (`website` `unlink` removes them by key while the
    registry is not ready) and all their descendants (`force_delete`).
    They are still in the database when this script runs and must not be
    taken into account when checking the inheritance of the other views.
    """
    cr = env.cr
    modules = tuple(env.registry.updated_modules)
    # only defined while the registry is loading
    loaded = getattr(env.registry, "loaded_xmlids", None)
    if not modules or loaded is None:
        return set()
    cr.execute(
        """
        SELECT d.module || '.' || d.name, d.res_id
        FROM ir_model_data d
        WHERE d.model = 'ir.ui.view'
            AND d.module IN %s
            AND NOT COALESCE(d.noupdate, FALSE)
            AND d.res_id IS NOT NULL
            -- a view whose page was loaded is kept (_inherits children rule)
            AND NOT EXISTS (
                SELECT 1 FROM website_page p
                JOIN ir_model_data pd
                    ON pd.model = 'website.page' AND pd.res_id = p.id
                WHERE p.view_id = d.res_id
                    AND pd.module || '.' || pd.name IN %s
            )
        """,
        (modules, tuple(loaded) or ("",)),
    )
    stale_ids = {res_id for xmlid, res_id in cr.fetchall() if xmlid not in loaded}
    if not stale_ids:
        return set()
    cr.execute(
        """
        WITH RECURSIVE removed AS (
            SELECT v.id FROM ir_ui_view v WHERE v.id IN %(ids)s
            UNION
            SELECT s.id FROM ir_ui_view s
            JOIN ir_ui_view g ON g.key = s.key
            WHERE g.id IN %(ids)s AND g.website_id IS NULL
                AND s.website_id IS NOT NULL AND g.type = 'qweb'
            UNION
            SELECT c.id FROM ir_ui_view c JOIN removed r ON c.inherit_id = r.id
        )
        SELECT id FROM removed
        """,
        {"ids": tuple(stale_ids)},
    )
    return {row[0] for row in cr.fetchall()}


def _db_only_extension_view_ids(cr, exclude_ids):
    """Active QWeb extension views that the module update does not refresh:
    website-specific copies and views without updatable XML-ID."""
    cr.execute(
        """
        SELECT v.id FROM ir_ui_view v
        WHERE v.type = 'qweb'
            AND v.active
            AND v.mode = 'extension'
            AND v.inherit_id IS NOT NULL
            AND (
                v.website_id IS NOT NULL
                OR NOT EXISTS (
                    SELECT 1 FROM ir_model_data d
                    WHERE d.model = 'ir.ui.view' AND d.res_id = v.id
                        AND NOT COALESCE(d.noupdate, FALSE)
                )
            )
        ORDER BY v.id
        """
    )
    return {row[0] for row in cr.fetchall()} - exclude_ids


class _RollbackCheck(Exception):
    pass


def _find_broken_db_views(env, candidate_ids):
    """Combine the template of every candidate view (in the context of its
    website) and return {view_id: error} for the candidates whose
    inheritance specs do not apply, deactivating them on the fly so the
    next ones are checked against what will remain."""
    from odoo.addons.base.models.ir_ui_view import IrUiView

    cr = env.cr
    broken = {}
    current = IrUiView.__dict__.get("_raise_view_error")
    if current is None:
        current = IrUiView._raise_view_error
    # openupgrade_framework only logs the inheritance errors: use the
    # original method, which raises, as a migrated database will do
    original = getattr(current, "_original_method", current)
    failing = []

    def _raise_view_error(
        self, message, node=None, *, from_exception=None, from_traceback=None
    ):
        failing.append(self.id)
        return original(
            self,
            message,
            node=node,
            from_exception=from_exception,
            from_traceback=from_traceback,
        )

    view_model = env["ir.ui.view"].with_context(load_all_views=True)
    checked = set()
    IrUiView._raise_view_error = _raise_view_error
    try:
        for view_id in sorted(candidate_ids):
            if view_id not in candidate_ids:
                continue
            view = view_model.browse(view_id)
            root = view
            while root.inherit_id and root.mode != "primary":
                root = root.inherit_id
            check_key = (root.id, view.website_id.id)
            if check_key in checked:
                continue
            context_view = root.with_context(website_id=view.website_id.id or False)
            for _attempt in range(20):
                failing.clear()
                try:
                    with cr.savepoint(flush=False):
                        context_view._get_combined_arch()
                    checked.add(check_key)
                    break
                except Exception as error:  # pylint: disable=broad-except
                    bad_ids = [vid for vid in failing if vid in candidate_ids]
                    if not bad_ids:
                        _logger.warning(
                            "Template %s (website %s) does not combine and no "
                            "database-only view is to blame: %s",
                            root.key,
                            view.website_id.id,
                            error,
                        )
                        checked.add(check_key)
                        break
                    bad_id = bad_ids[-1]
                    broken[bad_id] = str(error)
                    candidate_ids.discard(bad_id)
                    cr.execute(
                        "UPDATE ir_ui_view SET active = FALSE WHERE id = %s", (bad_id,)
                    )
                    view_model.invalidate_model(["active"])
                    env.transaction.invalidate_ormcache("templates")
    except Exception as error:  # pylint: disable=broad-except
        _logger.warning("Validation of database-only views stopped: %s", error)
    finally:
        IrUiView._raise_view_error = current
    return broken


def deactivate_broken_db_views(env):
    """Deactivate the database-only QWeb extension views (COW copies,
    customizations without XML-ID) whose specs do not apply anymore on the
    20.0 parent views.

    During the migration openupgrade_framework only logs inheritance errors;
    once migrated, Odoo raises them and every page using the template would
    answer an error 500. A deactivated view keeps its content and can be
    fixed and reactivated from the website editor/backend; each one is
    logged with its key.

    The views `_process_end` will delete right after this script are
    deactivated during the check (in a savepoint rolled back afterwards), so
    the check sees the templates as they will be once migrated.
    """
    cr = env.cr
    removed_ids = _views_removed_at_process_end(env)
    candidate_ids = _db_only_extension_view_ids(cr, removed_ids)
    if not candidate_ids:
        return
    broken = {}
    try:
        with cr.savepoint(flush=False):
            if removed_ids:
                cr.execute(
                    "UPDATE ir_ui_view SET active = FALSE WHERE id IN %s",
                    (tuple(removed_ids),),
                )
            env["ir.ui.view"].invalidate_model(["active"])
            env.transaction.invalidate_ormcache("templates")
            broken = _find_broken_db_views(env, candidate_ids)
            raise _RollbackCheck()
    except _RollbackCheck:
        pass
    env.invalidate_all()
    env.transaction.invalidate_ormcache("templates")
    if not broken:
        return
    cr.execute(
        "SELECT id, key, website_id FROM ir_ui_view WHERE id IN %s ORDER BY id",
        (tuple(broken),),
    )
    for view_id, key, website_id in cr.fetchall():
        _logger.warning(
            "Deactivating view %s (%s, website %s): its inheritance does not "
            "apply on the 20.0 template anymore: %s",
            view_id,
            key,
            website_id,
            broken[view_id],
        )
    openupgrade.logged_query(
        cr,
        "UPDATE ir_ui_view SET active = FALSE WHERE id IN %s",
        (tuple(broken),),
    )
    env["ir.ui.view"].invalidate_model(["active"])
    env.transaction.invalidate_ormcache("templates")


def check_db_only_templates_compile(env):
    """Log the database-only QWeb templates (pages, COW copies) that do not
    compile anymore with their 20.0 inherited views, to be fixed manually
    in the website editor (nothing is changed here)."""
    cr = env.cr
    removed_ids = _views_removed_at_process_end(env)
    cr.execute(
        """
        SELECT v.id, v.key, v.website_id FROM ir_ui_view v
        WHERE v.type = 'qweb' AND v.active AND v.mode = 'primary'
            AND (
                v.website_id IS NOT NULL
                OR EXISTS (SELECT 1 FROM website_page p WHERE p.view_id = v.id)
            )
        ORDER BY v.id
        """
    )
    for view_id, key, website_id in cr.fetchall():
        if view_id in removed_ids:
            continue
        qweb = env["ir.qweb"].with_context(website_id=website_id or False, lang="en_US")
        try:
            with cr.savepoint(flush=False):
                error = qweb._generate_code(view_id)[3]
        except Exception as exc:  # pylint: disable=broad-except
            error = (type(exc), str(exc), None)
        if error:
            _logger.warning(
                "Template %s (%s, website %s) does not compile on 20.0, fix it "
                "in the website editor: %s",
                view_id,
                key,
                website_id,
                error[1],
            )


@openupgrade.migrate()
def migrate(env, version):
    openupgrade.cow_templates_replicate_upstream(env.cr)
    delete_obsolete_generated_views(env)
    social_links_from_website(env)
    tcall_tset_to_attributes(env)
    fix_moved_qweb_calls(env)
    env["ir.ui.view"].invalidate_model(["arch_db", "inherit_id"])
    env.transaction.invalidate_ormcache("templates")
    create_missing_specific_views(env)
    deactivate_broken_db_views(env)
    check_db_only_templates_compile(env)
    env.transaction.invalidate_ormcache("templates")
